// Clean and prepare text for AI processing
const rawText = $input.item.binary?.data?.data?.toString('utf-8') || $input.item.json.data || '';

// Remove common OCR artifacts
let cleanText = rawText
  .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F-\x9F]/g, '') // Control characters
  .replace(/\f/g, '\n') // Form feeds
  .replace(/[\r\n]{3,}/g, '\n\n') // Multiple newlines
  .replace(/[ \t]+/g, ' ') // Multiple spaces
  .replace(/^[ \t]+|[ \t]+$/gm, ''); // Leading/trailing spaces per line

// Split into manageable chunks (max 3000 words per chunk for LLM processing)
const words = cleanText.split(/\s+/);
const chunkSize = 3000;
const chunks = [];

for (let i = 0; i < words.length; i += chunkSize) {
  const chunk = words.slice(i, i + chunkSize).join(' ');
  if (chunk.trim().length > 500) { // Only include substantial chunks
    chunks.push({
      index: Math.floor(i / chunkSize),
      text: chunk,
      word_count: chunk.split(/\s+/).length,
      char_count: chunk.length
    });
  }
}

// Limit to first 5 chunks to avoid overwhelming processing
const limitedChunks = chunks.slice(0, 5);

return limitedChunks.map(chunk => ({
  json: {
    chunk_index: chunk.index,
    text_content: chunk.text,
    word_count: chunk.word_count,
    char_count: chunk.char_count,
    book_info: $input.item.json.book_info,
    processing_timestamp: new Date().toISOString()
  }
}));

