const response = $input.item.json;
const textContent = response.candidates?.[0]?.content?.parts?.[0]?.text || '{"facts": []}';

let factsData;
try {
  factsData = JSON.parse(textContent);
} catch (e) {
  // Fallback if JSON parsing fails
  factsData = { facts: [] };
}

const facts = factsData.facts || [];

return facts.map((fact, index) => ({
  json: {
    fact_id: `${$node['Clean & Chunk Text'].json.book_info.identifier}_chunk${$node['Clean & Chunk Text'].json.chunk_index}_fact${index}`,
    fact: fact.fact,
    why_interesting: fact.why_interesting,
    viral_angle: fact.viral_angle,
    keywords: fact.keywords || [],
    source_book: $node['Clean & Chunk Text'].json.book_info,
    chunk_index: $node['Clean & Chunk Text'].json.chunk_index,
    extracted_timestamp: new Date().toISOString()
  }
}));

// Score and select best fact for video
const allFacts = $input.all();

if (allFacts.length === 0) {
  throw new Error('No facts extracted from the book');
}

// Simple scoring: prioritize unique keywords and viral angles
const scoredFacts = allFacts.map(item => {
  const fact = item.json;
  let score = 0;

  // Length score (prefer substantial but not too long facts)
  const factLength = fact.fact.length;
  if (factLength > 100 && factLength < 400) score += 10;

  // Keyword diversity score
  score += (fact.keywords?.length || 0) * 2;

  // Viral angle present
  if (fact.viral_angle && fact.viral_angle.length > 20) score += 15;

  // Random factor for variety
  score += Math.random() * 5;

  return {
    ...fact,
    score: score
  };
});

